r"""Hopping-site lattices and energetic / positional / off-diagonal disorder.

A :class:`Lattice` holds a periodic simple-cubic box of ``Lx*Ly*Lz`` sites
(lattice constant ``a``; internally all lengths are in units of ``a``), a
neighbour table up to a cutoff radius, and the site energies.

Disorder models
---------------
* ``gaussian``   - uncorrelated Gaussian DOS (Bässler GDM).
* ``dipolar``    - correlated disorder generated by randomly oriented
  permanent dipoles on every site (Dunlap/Novikov CDM); energies are
  computed by an FFT lattice sum and rescaled to the requested sigma.
* ``smoothed``   - Gaussian-filtered random field with correlation length
  ``xi`` (generic short-range correlated disorder).
* ``exponential``- exponential DOS (multiple-trapping-like tails).
* ``bimodal``    - host Gaussian + a fraction of trap / guest sites
  (host-guest systems, OLED emitter doping).
Off-diagonal disorder (Bässler Sigma) multiplies each bond by
:math:`e^{\Gamma_i+\Gamma_j}`, Gamma Gaussian with variance Sigma^2/2.
Positional disorder displaces sites by a Gaussian of width ``pos_sigma``.
"""
import numpy as np


def neighbour_offsets(rc):
    """Integer offsets (dx,dy,dz) with 0 < |d| <= rc (lattice units)."""
    n = int(np.floor(rc))
    rng = np.arange(-n, n + 1)
    g = np.array(np.meshgrid(rng, rng, rng, indexing="ij")).reshape(3, -1).T
    d = np.sqrt((g ** 2).sum(1))
    m = (d > 0) & (d <= rc + 1e-9)
    g = g[m]
    return g[np.argsort(np.sqrt((g ** 2).sum(1)), kind="stable")]


class Lattice:
    """Periodic cubic hopping lattice.

    Parameters
    ----------
    shape : int or (Lx, Ly, Lz)
    a : float
        lattice constant in metres (only used to convert to SI).
    rc : float
        hopping cutoff radius in units of a (sqrt(3) reproduces Pasveer 2005).
    seed : int
    """

    def __init__(self, shape=30, a=1.6e-9, rc=np.sqrt(3.0), seed=None):
        if np.isscalar(shape):
            shape = (int(shape),) * 3
        self.shape = tuple(int(s) for s in shape)
        self.N = int(np.prod(self.shape))
        self.a = float(a)
        self.rc = float(rc)
        self.rng = np.random.default_rng(seed)
        Lx, Ly, Lz = self.shape
        idx = np.arange(self.N)
        self.ijk = np.stack(np.unravel_index(idx, self.shape), axis=1)
        self.offsets = neighbour_offsets(rc)
        self.M = len(self.offsets)
        nb = (self.ijk[:, None, :] + self.offsets[None, :, :]) % np.array(self.shape)
        self.nbr = np.ravel_multi_index(nb.transpose(2, 0, 1), self.shape).astype(np.int64)
        self.disp = np.repeat(self.offsets[None, :, :].astype(float), self.N, axis=0)
        self.dist = np.sqrt((self.disp ** 2).sum(-1))
        self.energy = np.zeros(self.N)
        self.gamma = np.zeros(self.N)       # off-diagonal disorder
        self.sigma = 0.0

    # ------------------------------------------------------------------
    def add_positional_disorder(self, pos_sigma):
        """Gaussian site displacement (units of a); updates bond vectors."""
        u = self.rng.normal(0.0, pos_sigma, size=(self.N, 3))
        self.disp = self.disp + u[self.nbr] - u[:, None, :]
        self.dist = np.sqrt((self.disp ** 2).sum(-1))
        return self

    def add_offdiagonal_disorder(self, Sigma):
        """Bässler off-diagonal disorder: ln(overlap) gets Gamma_i+Gamma_j."""
        self.gamma = self.rng.normal(0.0, Sigma / np.sqrt(2.0), size=self.N)
        return self

    # ------------------------------------------------------------------
    def set_disorder(self, sigma, model="gaussian", **kw):
        """Draw site energies (eV) with standard deviation ``sigma``."""
        self.sigma = float(sigma)
        N, rng = self.N, self.rng
        if model == "gaussian":
            e = rng.normal(0.0, 1.0, N)
        elif model == "dipolar":
            e = self._dipolar_field()
        elif model == "smoothed":
            e = self._smoothed_field(kw.get("xi", 1.0))
        elif model == "exponential":
            # exponential tail g(E) ~ exp(E/E0), E<0 ; E0 = sigma
            e = -rng.exponential(1.0, N)
            e = e - e.mean()
            self.energy = e * sigma
            return self
        elif model == "bimodal":
            frac, depth = kw.get("trap_fraction", 0.01), kw.get("trap_depth", 0.3)
            e = rng.normal(0.0, 1.0, N) * sigma
            traps = rng.random(N) < frac
            st = kw.get("trap_sigma", sigma)
            e[traps] = -depth + rng.normal(0.0, 1.0, traps.sum()) * st
            self.trap_mask = traps
            self.energy = e
            return self
        else:
            raise ValueError(model)
        e = (e - e.mean()) / e.std()
        self.energy = e * sigma
        return self

    def _smoothed_field(self, xi):
        w = self.rng.normal(size=self.shape)
        k = [np.fft.fftfreq(n) * 2 * np.pi for n in self.shape]
        KX, KY, KZ = np.meshgrid(*k, indexing="ij")
        filt = np.exp(-0.5 * xi ** 2 * (KX ** 2 + KY ** 2 + KZ ** 2))
        f = np.real(np.fft.ifftn(np.fft.fftn(w) * filt))
        return f.ravel()

    def _dipolar_field(self):
        """Potential energy from random unit dipoles on every site (CDM)."""
        Lx, Ly, Lz = self.shape
        p = self.rng.normal(size=(3,) + self.shape)
        p /= np.sqrt((p ** 2).sum(0))
        # minimum-image kernel r/|r|^3
        gx = np.fft.fftfreq(Lx) * Lx
        gy = np.fft.fftfreq(Ly) * Ly
        gz = np.fft.fftfreq(Lz) * Lz
        X, Y, Z = np.meshgrid(gx, gy, gz, indexing="ij")
        R = np.sqrt(X ** 2 + Y ** 2 + Z ** 2)
        R[0, 0, 0] = np.inf
        phi = np.zeros(self.shape)
        for comp, Kc in zip(p, (X, Y, Z)):
            ker = Kc / R ** 3
            phi += np.real(np.fft.ifftn(np.fft.fftn(comp) * np.fft.fftn(ker)))
        return phi.ravel()

    # ------------------------------------------------------------------
    def bond_dE(self, F_red=(0.0, 0.0, 0.0)):
        """Energy difference for every bond (eV-units of the stored energy).

        ``F_red`` is the field as an energy drop per lattice constant, e*F*a
        in eV, along (x,y,z). A positive carrier gains energy -eF.dr.
        """
        F = np.asarray(F_red, dtype=float)
        return self.energy[self.nbr] - self.energy[:, None] - self.disp @ F

    def rates(self, T, F_red=(0.0, 0.0, 0.0), kind="ma", nu0=1e12, alpha=10.0,
              J0=0.01, lam=0.2, hw=0.17, S=1.0):
        """Rate table W[i, m] for hop i -> nbr[i, m] (1/s).

        ``alpha`` is the inverse localisation length in units of 1/a.
        """
        from . import rates as R
        dE = self.bond_dE(F_red)
        code = {"ma": R.RATE_MA, "marcus": R.RATE_MARCUS,
                "sym_ma": R.RATE_SYM_MA, "mlj": R.RATE_MLJ}[kind]
        W = R.rate_by_code(code, dE, self.dist, T, nu0=nu0, alpha=alpha, J0=J0,
                           lam=lam, hw=hw, S=S)
        if np.any(self.gamma):
            W = W * np.exp(self.gamma[:, None] + self.gamma[self.nbr])
        return W
